  async void Run(Func<CancellationToken,string> task,Action<string> complete){if(cancel!=null)return;cancel=new CancellationTokenSource();SetBusy(true);((ProgressBar)Window.FindName("ProgressBar")).IsIndeterminate=true;latestProgress=new ProgressInfo{Stage="Preparing",Text="Checking folders and availability"};string result=null;bool success=false;try{result=await Task.Run(()=>task(cancel.Token));Refresh();success=true;}catch(OperationCanceledException){Refresh();L("StatusLabel").Text="Canceled. Completed imports are retained; scan again to resume.";}catch(Exception e){Refresh();MessageBox.Show(Window,e.Message,"Operation could not finish",MessageBoxButton.OK,MessageBoxImage.Warning);}finally{LiveTick(true);latestProgress=null;activeMetrics=null;cancel.Dispose();cancel=null;SetBusy(false);((ProgressBar)Window.FindName("ProgressBar")).IsIndeterminate=false;if(closing)Window.Close();}if(success&&!closing&&complete!=null)complete(result);}
  void Scan(){if(repo==null)return;string source=T("SourceBox").Text.Trim(),id=T("TelescopeBox").Text.Trim(),model=Convert.ToString(C("ModelBox").SelectedItem),camera=Convert.ToString(C("CameraBox").SelectedItem);if(string.IsNullOrWhiteSpace(id)){MessageBox.Show(Window,"Give this physical telescope a unique ID.","Telescope ID required");return;}bool cloud=((CheckBox)Window.FindName("CloudSourceCheck")).IsChecked==true;SaveSettings();plan=null;BeginLive(true);((CheckBox)Window.FindName("DeleteOriginalsCheck")).IsChecked=false;
