  void Import(){if(plan==null||repo==null)return;string solve=Convert.ToString(C("ImportSolveMode").SelectedItem),rotation=Convert.ToString(C("ImportRotationMode").SelectedItem);if(solve!="Off"&&!PlateSolve.Configured(settings)){Configure();if(!PlateSolve.Configured(settings))return;}var options=new ImportOptions{DeleteOriginals=((CheckBox)Window.FindName("DeleteOriginalsCheck")).IsChecked==true,SourceRoot=plan.Source,Workers=settings.CopyWorkers,Retune=((CheckBox)Window.FindName("RetuneCheck")).IsChecked==true,CloudSource=((CheckBox)Window.FindName("CloudSourceCheck")).IsChecked==true,OnFrame=LiveFrame,ScanMetrics=plan.Metrics};ImportResult result=null;BeginLive(false);
   Run(ct=>{result=repo.Import(plan.Frames,ct,Progress,options);activeMetrics=result.Metrics;var hashes=new HashSet<string>(plan.Frames.Where(f=>f.Status=="Imported").Select(f=>f.Hash));var added=repo.All().Where(f=>hashes.Contains(f.Hash)).ToList();if(solve!="Off"){var candidates=added.Where(f=>(f.Kind=="Light"||f.Kind=="Stack")&&(solve=="All light/stack files"||TargetIdentification.NeedsPlateSolve(f))).ToList();AutoIdentify(candidates,ct,result.Metrics,solve=="All light/stack files");}if(rotation!="Off"){var groups=added.Where(f=>f.Kind=="Light"&&!(f.MountEvidence??"").StartsWith("User")&&(rotation=="All light sessions"||f.Mount=="Unknown")).GroupBy(f=>f.Session+"|"+f.Group).ToList();result.Metrics.Phase(groups.Count,0);foreach(var group in groups){ct.ThrowIfCancellationRequested();using(var stage=result.Metrics.Begin("Rotation",group.First().Target)){try{AnalyzeGroup(group.Select(f=>f.Clone()).ToList(),ct,n=>stage.Bytes(n));}catch(OperationCanceledException){throw;}catch(Exception e){result.Warnings.Add(FileRetry.Detail(group.First().OriginalName,e));}finally{stage.Complete(group.Count());}}result.Metrics.Complete(0);}}
