    FitsImage image=items.Count>1?Fits.Image(repo.FilePath(sample),ct,n=>stage.Bytes(n)):null;var stars=image==null?null:Rotation.Detect(image);foreach(var f in items.Where(f=>f!=sample)){try{repo.ValidateCapture(f,ct);var other=Fits.Image(repo.FilePath(f),ct,n=>stage.Bytes(n));if(other.Width!=image.Width||other.Height!=image.Height)throw new InvalidDataException("Different dimensions.");Rotation.Match(stars,Rotation.Detect(other),image.Width,image.Height,ct);f.Target=solution.Suggested;f.TargetEvidence="Matched to a plate-solved session frame";f.RA=solution.RA;f.Dec=solution.Dec;}catch(OperationCanceledException){throw;}catch{f.Notes+="No reliable common stars with solved reference. ";}}foreach(var f in items){repo.Refile(f,ct);LiveFrame(f);}
