  void Analyze(){if(repo==null)return;var chosen=Context().Where(f=>f.Kind=="Light").ToList();if(chosen.Count==0){MessageBox.Show(Window,"Choose a target with individual light frames. Stacks cannot establish acquisition rotation.","Individual subs required");return;}var ids=new HashSet<string>(chosen.Select(f=>f.Session+"|"+f.Group));var groups=all.Where(f=>f.Kind=="Light"&&ids.Contains(f.Session+"|"+f.Group)).GroupBy(f=>f.Session+"|"+f.Group).Select(g=>g.Select(f=>f.Clone()).ToList()).ToList();
   Run(ct=>{var reports=new List<string>();foreach(var g in groups){ct.ThrowIfCancellationRequested();var result=AnalyzeGroup(g,ct);reports.Add(g[0].Target+" / "+g[0].Telescope+" / "+g[0].Night+"\r\n"+result.Mount+"\r\n"+result.Evidence+"\r\n"+string.Join("\r\n",result.Points.Select(p=>p.Minutes.ToString("0.0")+" min  "+p.Angle.ToString("0.000")+"°  "+p.Stars+" stars  "+p.Rms.ToString("0.00")+" px"))+"\r\n"+string.Join("\r\n",result.Rejected));}return string.Join("\r\n\r\n",reports);},r=>{L("StatusLabel").Text="Rotation analysis complete.";ShowReport("Rotation analysis",r);});}
  bool PendingImport(Frame frame,bool imported){return imported&&(frame.Status=="New"||frame.Status=="Restore"||frame.Status=="Duplicate in source"||frame.Status=="Failed"||frame.Status=="Unreadable");}
  string CapturePath(Frame frame,bool imported){return PendingImport(frame,imported)?frame.SourcePath:repo.FilePath(frame);}
  void StoreIdentification(Frame original,Frame updated,bool imported,CancellationToken ct){if(!PendingImport(original,imported))repo.Refile(updated,ct);if(imported){original.Target=updated.Target;original.TargetEvidence=updated.TargetEvidence;original.Notes=updated.Notes;original.RA=updated.RA;original.Dec=updated.Dec;original.RelativePath=updated.RelativePath;}}
  void Identify(bool imported){if(repo==null)return;var selected=Context(imported).Where(f=>f.Kind=="Light"||f.Kind=="Stack"||f.Kind=="Unknown").ToList();if(selected.Count==0){MessageBox.Show(Window,"Select a light exposure or telescope stack to identify.","Select a capture");return;}
   var named=selected.Where(f=>Catalog.TargetFromFilename(f.OriginalName)!=null).ToList();var unresolved=selected.Except(named).ToList();int identified=0;
   if(named.Count==0){IdentifyByPlate(imported,unresolved,0);return;}
   Run(ct=>{foreach(var original in named){ct.ThrowIfCancellationRequested();Frame updated=original.Clone();if(TargetIdentification.ApplyFilename(updated)){StoreIdentification(original,updated,imported,ct);identified++;}}return identified+" captures identified from filenames.";},message=>{if(imported)G("ImportGrid").Items.Refresh();L("StatusLabel").Text=message;if(unresolved.Count>0)IdentifyByPlate(imported,unresolved,identified);});
  }
  void IdentifyByPlate(bool imported,List<Frame> selected,int named){
   if(!PlateSolve.Configured(settings)){Configure();if(!PlateSolve.Configured(settings)){L("StatusLabel").Text=named+" identified from filenames; "+selected.Count+" require a configured plate solver.";return;}}
   var groups=selected.GroupBy(f=>f.MakeText+"|"+f.Telescope+"|"+f.Session+"|"+f.Width+"x"+f.Height+"|"+f.Camera).Select(g=>g.ToList()).ToList();int index=0,solved=0,unresolved=0;Action next=null;
   next=()=>{if(closing)return;if(index>=groups.Count){L("StatusLabel").Text=named+" identified from filenames; "+solved+" plate solved; "+unresolved+" unresolved.";return;}var items=groups[index++];Frame sample=items.FirstOrDefault(f=>f.Kind=="Stack")??items.First();SolveResult solution=null;string failure=null;
    Run(ct=>{try{solution=PendingImport(sample,imported)?PlateSolve.Solve(CapturePath(sample,imported),settings,ct,t=>Progress(new ProgressInfo{Stage="Target identification",Text=t})):repo.CachedSolve(sample,settings,ct,t=>Progress(new ProgressInfo{Stage="Target identification",Text=t}));}catch(OperationCanceledException){throw;}catch(Exception e){failure=e.Message;}return "";},message=>{
     if(failure!=null){unresolved+=items.Count;foreach(var item in items)item.Notes=(item.Notes??"")+"Plate solve unavailable: "+failure+". ";if(imported)G("ImportGrid").Items.Refresh();next();return;}
     string target=solution.Suggested??ChooseTarget(solution);if(target==null){L("StatusLabel").Text="Identification stopped: "+named+" filename matches and "+solved+" plate-solved captures completed.";return;}
     Run(ct=>{FitsImage reference=items.Count>1?Fits.Image(CapturePath(sample,imported),ct):null;var stars=reference!=null?Rotation.Detect(reference):null;foreach(var original in items){ct.ThrowIfCancellationRequested();Frame updated=original.Clone();try{if(original!=sample){FitsImage image=Fits.Image(CapturePath(original,imported),ct);if(image.Width!=reference.Width||image.Height!=reference.Height)throw new InvalidDataException("Different dimensions.");Rotation.Match(stars,Rotation.Detect(image),reference.Width,reference.Height,ct);}updated.Target=target;updated.TargetEvidence="Plate solved using "+solution.Solver+(original==sample?"":"; verified common stars with solved frame");updated.RA=solution.RA;updated.Dec=solution.Dec;updated.Notes=(updated.Notes??"")+updated.TargetEvidence+". ";StoreIdentification(original,updated,imported,ct);solved++;}catch(OperationCanceledException){throw;}catch(Exception e){unresolved++;if(imported)original.Notes=(original.Notes??"")+"Identification retained for review: "+e.Message+". ";}}return "";},done=>{if(imported)G("ImportGrid").Items.Refresh();next();});
    });
   };next();
  }
  string ChooseTarget(SolveResult result){var d=new FormWindow(Window,"Identify target",660,620);d.Text("Solved centre: RA "+result.RA.ToString("0.00000")+"°, Dec "+result.Dec.ToString("0.00000")+"°",true);d.Text("A plate solution locates the field. Select the intended target from nearby candidates or search the catalogue.");TextBox search=d.Input("Search catalogue or enter a custom target",result.Suggested??"");var list=new ListBox{Height=265,DisplayMemberPath="Name",Margin=new Thickness(0,8,0,12),BorderBrush=Brushes.LightGray,BorderThickness=new Thickness(1)};list.ItemsSource=result.Candidates;d.Add(list);var detail=new TextBlock{TextWrapping=TextWrapping.Wrap,Foreground=Brushes.SlateGray,Margin=new Thickness(0,0,0,8)};d.Add(detail);list.SelectionChanged+=(s,e)=>{var c=list.SelectedItem as Candidate;if(c!=null){search.Text=c.Name;detail.Text=c.Common+"  ·  "+c.DistanceText;}};search.TextChanged+=(s,e)=>{if(list.IsKeyboardFocusWithin)return;if(search.IsKeyboardFocusWithin&&search.Text.Length>=2)list.ItemsSource=Catalog.Search(search.Text).Select(o=>new Candidate{Name=o.Name,Common=o.Common,Separation=Catalog.Distance(result.RA,result.Dec,o.RA,o.Dec)}).ToList();};d.Accept("Use target",()=>!string.IsNullOrWhiteSpace(search.Text));return d.Show()?Catalog.Normalize(search.Text):null;}
  void Edit(bool imported){if(repo==null)return;var selected=Context(imported);if(selected.Count==0)return;var f=selected.First();var d=new FormWindow(Window,"Edit metadata",610,750);d.Text(selected.Count+" selected captures. Empty fields keep their existing values.");TextBox target=d.Input("Target",selected.Select(x=>x.Target).Distinct().Count()==1?f.Target:""),telescope=d.Input("Physical telescope ID",selected.Select(x=>x.Telescope).Distinct().Count()==1?f.Telescope:""),camera=d.Input("Camera channel",selected.Select(x=>x.Camera).Distinct().Count()==1?f.Camera:"");ComboBox model=d.Select("Instrument model",new[]{"Keep existing","Seestar S50 Pro","Seestar S50","Seestar S30 Pro","Seestar S30","Dwarf 3","Dwarf II","Dwarf mini","Other"},"Keep existing"),kind=d.Select("Frame type",new[]{"Keep existing","Light","Stack","Dark","Master dark","Flat","Master flat","Bias","Master bias","Unknown","Auxiliary"},"Keep existing"),mount=d.Select("Mount mode",new[]{"Keep existing","EQ","Alt/Az","Unknown"},"Keep existing"),cal=d.Select("Calibration state",new[]{"Keep existing","Unknown","Uncalibrated","Calibrated","Registered","Device stack","Calibration frame"},"Keep existing");TextBox filter=d.Input("Filter",selected.Select(x=>x.Filter).Distinct().Count()==1?f.Filter:""),exp=d.Input("Exposure seconds (optional)",""),gain=d.Input("Gain (optional)",""),temp=d.Input("Sensor temperature °C (optional)",""),bin=d.Input("Binning x × y (optional, e.g. 1x1)","");CheckBox sessions=d.Check("Apply to entire selected sessions",false);d.Accept("Save metadata",()=>{foreach(var box in new[]{exp,gain,temp})if(box.Text.Length>0&&!ParseOptional(box.Text).HasValue){MessageBox.Show(d.Window,"Use decimal numbers with a dot.");return false;}if(bin.Text.Length>0&&!System.Text.RegularExpressions.Regex.IsMatch(bin.Text,@"^[1-9][0-9]?[xX*][1-9][0-9]?$")){MessageBox.Show(d.Window,"Enter binning as 1x1, 2x2, etc.");return false;}return true;});if(!d.Show())return;
   var items=selected;if(sessions.IsChecked==true){var ids=new HashSet<string>(selected.Select(x=>x.Session));items=(imported?plan.Frames:all).Where(x=>ids.Contains(x.Session)).ToList();}
   string newTarget=target.Text.Trim(),newTel=telescope.Text.Trim(),newCamera=camera.Text.Trim(),newModel=Convert.ToString(model.SelectedItem),newKind=Convert.ToString(kind.SelectedItem),newMount=Convert.ToString(mount.SelectedItem),newCal=Convert.ToString(cal.SelectedItem),newFilter=filter.Text.Trim(),newBin=bin.Text.Trim();double? newExp=ParseOptional(exp.Text),newGain=ParseOptional(gain.Text),newTemp=ParseOptional(temp.Text);
   Run(ct=>{foreach(var original in items){ct.ThrowIfCancellationRequested();Frame item=original.Clone();if(newTarget.Length>0){item.Target=Catalog.Normalize(newTarget);item.TargetEvidence="User assigned";}if(newTel.Length>0)item.Telescope=newTel;if(newCamera.Length>0)item.Camera=newCamera;if(newModel!="Keep existing"){item.Model=newModel;item.Make=InstrumentDetection.MakeOf(newModel);item.MakeEvidence="User-selected model";}if(newKind!="Keep existing")item.Kind=newKind;if(newMount!="Keep existing"){item.Mount=newMount;item.MountEvidence="User assigned";}if(newCal!="Keep existing")item.Calibration=newCal;if(newFilter.Length>0)item.Filter=newFilter;if(newExp.HasValue)item.Exposure=newExp;if(newGain.HasValue)item.Gain=newGain;if(newTemp.HasValue)item.Temperature=newTemp;if(newBin.Length>0){string[] bins=newBin.ToLowerInvariant().Split(new[]{'x','*'});item.BinX=int.Parse(bins[0]);item.BinY=int.Parse(bins[1]);}if(!PendingImport(original,imported))repo.Refile(item,ct);if(imported){int row=plan.Frames.IndexOf(original);if(row>=0)plan.Frames[row]=item;}}return items.Count+" captures updated.";},r=>{if(imported)G("ImportGrid").Items.Refresh();L("StatusLabel").Text=r;});}
  static double? ParseOptional(string s){double v;return double.TryParse(s,NumberStyles.Float,CultureInfo.InvariantCulture,out v)&&!double.IsNaN(v)&&!double.IsInfinity(v)?(double?)v:null;}
  void Configure(){var d=new FormWindow(Window,"Settings",680,760);d.Text("Active repository",true);TextBox repository=d.Input("Archive folder",settings.Repository??"");repository.IsReadOnly=true;d.Button("Choose repository folder",()=>{string p=Folder("Choose your local repository",repository.Text,d.Window);if(p!=null)repository.Text=p;});d.Text("The active path appears above the capture library. A change takes effect when you save settings.");d.Text("App releases",true);d.Button("Check for and download new releases",()=>Releases(d.Window));d.Text("Plate solving",true);d.Text("Use local ASTAP with an installed star database, or Astrometry.net with your own API key. Online solving sends detected star coordinates, never the full image.");TextBox astap=d.Input("ASTAP executable",settings.Astap??"");d.Button("Browse ASTAP",()=>{var p=new OpenFileDialog{Filter="Windows executable|*.exe",Title="Choose ASTAP executable"};if(p.ShowDialog(d.Window)==true)astap.Text=p.FileName;});TextBox database=d.Input("ASTAP star database folder (blank uses ASTAP default)",settings.StarDatabase??"");d.Button("Browse star database",()=>{string p=Folder("ASTAP star database folder",database.Text,d.Window);if(p!=null)database.Text=p;});TextBox fov=d.Input("ASTAP image height in degrees (blank: automatic; useful for wide cameras)",settings.FieldHeight.HasValue?Util.Num(settings.FieldHeight):"");CheckBox online=d.Check("Use Astrometry.net instead of ASTAP",settings.UseOnline);var label=new TextBlock{Text="Astrometry.net API key (saved with Windows user encryption)",Margin=new Thickness(0,8,0,5)};d.Add(label);var key=new PasswordBox{Password=PlateSolve.Unprotect(settings.ApiKeyProtected),Padding=new Thickness(10,8,10,8)};d.Add(key);d.Text("Solving and rotation are off by default. Choose their scope in Import; both can take much longer than copying.");ComboBox workers=d.Select("Copy workers",new[]{"Auto (start at 1, benchmark 1/2/4/8)","1","2","4","8"},settings.CopyWorkers==0?"Auto (start at 1, benchmark 1/2/4/8)":settings.CopyWorkers.ToString());d.Text("Auto compares four real 16-file import batches when at least 64 files / 64 MB are ready. It retains a faster setting for this source/repository pair; Retune repeats the pilot. Storage and file sizes affect the result.");d.Text("Observing site",true);d.Text("Latitude north-positive and longitude east-positive, in degrees. Used with UTC timestamps and pointing coordinates to test predicted Alt/Az field rotation.");TextBox lat=d.Input("Latitude",settings.Latitude.HasValue?Util.Num(settings.Latitude):""),lon=d.Input("Longitude",settings.Longitude.HasValue?Util.Num(settings.Longitude):"");d.Text("Archive data",true);var delete=new Button{Content="Delete all archive data",Background=new SolidColorBrush(Color.FromRgb(183,40,51)),BorderBrush=new SolidColorBrush(Color.FromRgb(183,40,51)),Foreground=Brushes.White,HorizontalAlignment=HorizontalAlignment.Left};delete.IsEnabled=repo!=null;delete.Click+=(s,e)=>{d.Window.Close();ResetArchive();};d.Add(delete);d.Accept("Save settings",()=>{double? la=ParseOptional(lat.Text),lo=ParseOptional(lon.Text);if((lat.Text.Length>0&&!la.HasValue)||(lon.Text.Length>0&&!lo.HasValue)||(la.HasValue&&Math.Abs(la.Value)>90)||(lo.HasValue&&Math.Abs(lo.Value)>180)||la.HasValue!=lo.HasValue){MessageBox.Show(d.Window,"Enter both coordinates with a decimal dot: latitude -90 to 90, longitude -180 to 180, or leave both blank.");return false;}double? field=ParseOptional(fov.Text);if(fov.Text.Length>0&&(!field.HasValue||field<=0||field>180)){MessageBox.Show(d.Window,"Image height must be greater than 0 and no more than 180 degrees.");return false;}if(online.IsChecked==true&&string.IsNullOrWhiteSpace(key.Password)){MessageBox.Show(d.Window,"Enter your Astrometry.net API key to enable online solving.");return false;}return true;});if(!d.Show())return;if(!string.IsNullOrWhiteSpace(repository.Text)){try{OpenRepository(repository.Text,false);}catch(Exception e){MessageBox.Show(Window,e.Message,"Repository could not be opened",MessageBoxButton.OK,MessageBoxImage.Warning);return;}}settings.FieldHeight=ParseOptional(fov.Text);settings.Astap=astap.Text.Trim();settings.StarDatabase=database.Text.Trim();settings.UseOnline=online.IsChecked==true;settings.AutoSolve=false;settings.AutoRotation=false;int workerCount;settings.CopyWorkers=int.TryParse(Convert.ToString(workers.SelectedItem),out workerCount)?workerCount:0;settings.ApiKeyProtected=PlateSolve.Protect(key.Password);settings.Latitude=ParseOptional(lat.Text);settings.Longitude=ParseOptional(lon.Text);SaveSettings();L("StatusLabel").Text="Settings saved.";}
  void ResetArchive(){if(repo==null||cancel!=null)return;var files=repo.All();var dialog=new FormWindow(Window,"Delete all archive data",650,550);dialog.Text("Permanently delete this archive",true);dialog.Text(repo.Root);dialog.Text(files.Count+" indexed FITS files ("+(files.Sum(f=>f.Bytes)/1000000000.0).ToString("0.00")+" GB), session metadata, analysis cache, worker profiles and reports will be removed. Source folders and unindexed files stay. Deletions in a synced repository propagate to the cloud. There is no undo.");dialog.Text("Drag the slider fully right, then press Delete permanently.");var slider=new Slider{Minimum=0,Maximum=100,Value=0,TickFrequency=100,IsSnapToTickEnabled=false,Height=45,IsMoveToPointEnabled=false,Margin=new Thickness(0,10,0,12)};dialog.Add(slider);var button=new Button{Content="Delete permanently",IsEnabled=false,Background=new SolidColorBrush(Color.FromRgb(183,40,51)),BorderBrush=new SolidColorBrush(Color.FromRgb(183,40,51)),Foreground=Brushes.White};dialog.Add(button);bool dragged=false,confirmed=false;slider.AddHandler(Thumb.DragStartedEvent,new DragStartedEventHandler((s,e)=>{dragged=true;confirmed=false;button.IsEnabled=false;}));slider.AddHandler(Thumb.DragCompletedEvent,new DragCompletedEventHandler((s,e)=>{confirmed=dragged&&!e.Canceled&&slider.Value>=99;button.IsEnabled=confirmed;if(!confirmed)slider.Value=0;dragged=false;}));slider.PreviewKeyDown+=(s,e)=>{e.Handled=true;confirmed=false;button.IsEnabled=false;slider.Value=0;};button.Click+=(s,e)=>{if(confirmed&&slider.Value>=99)dialog.Window.DialogResult=true;};dialog.CloseOnly();if(!dialog.Show())return;incoming.Clear();Run(ct=>{var errors=repo.ResetArchive(ct,Progress);return errors.Count==0?"Archive cleared. Source folders and unindexed files retained.":"Some files were retained:\r\n"+string.Join("\r\n",errors);},message=>{plan=null;G("ImportGrid").ItemsSource=null;L("StatusLabel").Text=message;if(message.StartsWith("Some"))ShowReport("Archive reset",message);});}
  void More(){if(repo==null)return;var menu=new ContextMenu();Action<string,Action> add=(text,fn)=>{var m=new MenuItem{Header=text};m.Click+=(s,e)=>fn();menu.Items.Add(m);};add("Verify repository checksums",()=>Run(ct=>repo.Verify(ct,Progress).ToString(),r=>{L("StatusLabel").Text=r+" missing or changed files.";MessageBox.Show(Window,r=="0"?"All repository files match their recorded checksums.":r+" files are missing or changed. Re-scan the original mirror to restore them.","Verification complete");}));add("Index an existing repository",()=>{if(MessageBox.Show(Window,"Index existing FITS files in this repository without copying or moving them?\n\nUnknown telescope identities may need metadata corrections afterwards.","Index existing files",MessageBoxButton.OKCancel)==MessageBoxResult.OK)Run(ct=>{var p=repo.Scan(repo.Root,"Unknown","Auto",ct,Progress,true);return p.Frames.Count+" indexed.\r\n"+string.Join("\r\n",p.Errors);},r=>ShowReport("Indexing report",r));});add("Export searchable catalogue CSV",()=>{var d=new SaveFileDialog{FileName="AstroArchive_catalog.csv",Filter="CSV|*.csv"};if(d.ShowDialog(Window)==true){repo.ExportIndex(d.FileName);L("StatusLabel").Text="Catalogue CSV exported.";}});add("Show selected file location",()=>{var f=G("FramesGrid").SelectedItem as Frame;if(f!=null){string p=repo.FilePath(f);if(File.Exists(p))Process.Start(new ProcessStartInfo("explorer.exe","/select,\""+p+"\""){UseShellExecute=true});}});menu.PlacementTarget=B("MoreButton");menu.IsOpen=true;}
  void ShowReport(string title,string text){var d=new FormWindow(Window,title,820,640);var t=new TextBox{Text=text,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Height=460,FontFamily=new FontFamily("Consolas"),FontSize=12};d.Add(t);d.Button("Save report",()=>{var p=new SaveFileDialog{FileName=Util.Safe(title)+".txt",Filter="Text|*.txt"};if(p.ShowDialog(d.Window)==true)File.WriteAllText(p.FileName,text);});d.CloseOnly();d.Show();}
  void Guide(){ShowReport("AstroArchive guide",GuideText);}
  const string GuideText="AstroArchive 1.3.0\nWindows 10/11 x64 desktop app. Built-in .NET Framework 4.8 and Windows SQLite.\nNo installer, Python or Google login required.\n\nSTART HERE\n1. Open AstroArchive and choose your archive folder in Settings.\n2. Import: choose your telescope mirror and assign a unique physical device ID,\n   such as Seestar-01 or Dwarf-03. Leave model and camera on Auto unless you know\n   which override to apply. Scan folder, review the rows, then Import new files.\n3. Repository: search names, dates, devices, filter, exposure, gain or filename.\n   Clear resets the filters. It does not delete files.\n4. Select rows with Ctrl/Shift, or use all visible captures when none are selected.\n   Right-click selected files, then Export to copy files or create a ready-to-stack\n   folder, with matching calibrations if selected. Delete removes selected copies.\n   Settings includes repository selection and Check for and download new releases.\n\nWINDOWS FOLDER SELECTION AND GOOGLE DRIVE\nAll folder selectors use native Windows Explorer dialogs, with This PC, mounted\nvolumes, an address bar, search and Explorer cloud navigation. Cancel keeps the\nexisting selection. If a Drive entry is absent, copy the full Windows path from\nExplorer and paste it into the selector address bar with Alt+D. The selected\nlocation must expose a filesystem path; a browser-only Drive folder cannot be used.\n\nFor streamed Google Drive input, tick Streamed/cloud source before scanning.\nWindows placeholder attributes are detected automatically when available. Cloud\navailability time includes opening/reading provider-backed files, which may wait\nfor a download. Copy + source hash measures local output/hashing separately for\nthese inputs. The app cannot obtain a reliable Google Drive download percentage,\nand provider read time can include cached reads. In Drive/Explorer, making the\ninput available offline before importing avoids the on-demand download wait.\nCloud placeholder folders are traversed; directory junctions and symlinks are skipped.\n\nThe working SQLite index is local to your Windows user, even when the archive is\non Drive. Verified snapshots are written to .astroarchive/index.sqlite inside the\narchive. Keep that folder with the FITS files when moving/backing up the archive.\nA blocked snapshot is reported while the local committed index remains available.\nThe live Google Drive/Windows selector integration has not been tested here.\n\nIMPORT PROGRESS, PERFORMANCE AND RECOVERY\nRows appear during discovery and as each file changes to Copying, Imported,\nDuplicate or Failed. Repository rows appear as imports commit. The progress bar\nshows completed files and a throughput-based ETA once sufficient work is measured;\nscan totals and cloud/solver waiting can make the estimate change.\n\nExpand Performance details to compare discovery, metadata, duplicate checking,\ncopy + source hash, verification, cloud availability, target identification,\nrotation and index/checkpoint. The report includes stage seconds, files/s and\nprocessed MB/s. These are app work counters, not physical disk/network benchmarks.\nFITS gzip parsing counts decoded bytes; external ASTAP/database I/O is not measured.\nStage wall times can overlap when workers run concurrently and are not additive.\n\nScanning uses one directory enumeration and a bounded queue. FITS headers and\nsession JSON are read before expensive work; shared JSON is read once per scan.\nNew file hashes are deferred until copying, avoiding a separate full source read.\nSHA-256 is computed while writing a temporary copy. The destination is read back\nand verified before committing its file/index record. A matching name and size\nnever prove a duplicate. Verified, unchanged NTFS/ReFS files with stable identity\nand change metadata can skip payload reads. Unsupported/cloud filesystems use\ncontent hashing instead. Solving/rotation caches also validate archived content.\n\nSettings > Copy workers: Auto begins at 1. With at least 64 files and 64 MB it\ncompares four actual 16-file batches at 1, 2, 4 and 8 workers, and retains a faster\nsetting for that source/archive pair. Retune repeats the pilot. Differences in\nfile size, caching, storage and cloud downloads affect the result. Small imports\nstay conservative, and fixed 1/2/4/8-worker choices are available.\n\nTemporary file locks and provider I/O errors get limited retries. A failed file\nis shown with its full path, exception/error code and reason; later files continue.\nDisk-full errors stop the batch. Completed imports remain committed. Report opens\nthe diagnostics, also saved in .astroarchive/reports/last-import.txt. Free space or\nresolve the reported source problem, scan again and import to resume. Interrupted\nexports retain INCOMPLETE.txt; create a fresh project after an interrupted export.\nThe exact cause of the previously reported copying failure cannot be established\nwithout that PC's error; the new diagnostics are intended to make it identifiable.\n\nORIGINALS AFTER IMPORT\nDelete originals after verified import is OFF by default and resets after scans\nand imports. Only newly copied/restored FITS are eligible. Before removal, the app\nsaves the archive snapshot, checks the source stamp again, opens both files with\nWindows handles, resolves physical boundaries, and compares their SHA-256 hashes.\nA changed file, duplicate, overlapping root, identical hard link, lock or cleanup\nfailure retains the original with a reason. Session JSON, other files and source\nfolders stay. Deleting a cloud-synced original also propagates through its service.\n\nMAKE, MODEL AND DWARF CAMERA CLASSIFICATION\nMetadata and structure are considered per file, including MyWorks, EMMC Images,\nSeestar _sub folders, DWARF_RAW, DWARF_DARK, CALI_FRAME and shotsInfo.json. Shared\nstructures establish the make without inventing an exact DWARF model. Conflicts\nremain Unknown. Model/camera overrides and metadata edits are available.\n\nDWARF camera IDs and cam_0 folders identify telephoto; cam_1 identifies wide.\nExplicit tele/wide markers are used, including calibration folders. Dimensions or\nbinning alone do not establish the camera. Conflicting markers remain Unknown.\nTelephoto and wide calibration never share export groups or match one another.\nThis remains a FITS archive. DWARF factory PNG calibration needs conversion to\nFITS with the relevant camera metadata or preserved cam_0/cam_1 folder structure.\n\nTARGET IDENTIFICATION AND OPTIONAL ANALYSIS\nIdentify target first uses unambiguous catalogue IDs/common names in filenames,\nsuch as M33, NGC281 or Heart Nebula (IC1805), without needing a solver. Conflicting\nnames, HID labels and unrecognised niche targets use the configured plate solver.\nImported captures use the archive copy, so identification works after source removal.\n\nPlate solving and rotation are OFF by default. Import offers:\n- Plate solving: Off, Ambiguous only, or All light/stack files.\n- Rotation: Off, Ambiguous mounts only, or All light sessions.\nEnabling either can take substantially longer. Analysis runs after verified copying,\nuses cached results, and uses representative session frames where possible. Plate\nsolving propagates a result only when additional images match the solved star field.\nManual labels keep priority. Crowded fields and uncatalogued targets need review.\n\nConfigure local ASTAP and its star database in Settings, or your Astrometry.net\naccount/API key. The app bundles a 12,163-object deep-sky catalogue and solver\nintegrations, but no star database or online account.\nASTAP: https://www.hnsky.org/astap.htm\nWide cameras may need explicit image height in degrees and a suitable star database.\nASTAP uses temporary copies and does not edit the archive/original FITS.\nAstrometry.net: https://nova.astrometry.net\nThe API key is stored with Windows user encryption. Online solving submits detected\nstar coordinates as a FITS table, not image pixels, and requests non-public submissions.\n\nRotation uses timestamped acquisition subs, never stacks/registered frames. It samples\nup to 18 frames in the longest continuous segment, matches distributed stars and\nrejects poor residuals, reflections, scale changes or insufficient coverage. At least\nfive matches over ten minutes are needed. EQ inference needs observing latitude/\nlongitude and pointing evidence over at least fifteen minutes where Alt/Az predicts\nmeasurable rotation. Stable orientation without that evidence remains Unknown.\nBad polar alignment, camera movement and registered/derotated data can mislead the\ninference. Likely labels remain inferences; reports show measurements/rejections.\n\nSTACKING PROJECTS AND SESSIONS\nChoose Subs, Stacks or Both. Separate sessions into their own project subdirectories\nis OFF by default. OFF combines compatible sessions in each input group. ON creates\nsessions/<night>_<session>/subs and sessions/<night>_<session>/stacks, keeping each\nsession's inputs separate. Subs and stacks always stay in separate folder sets.\n\nSub groups separate make, physical device, camera, filter, dimensions, binning,\nBayer pattern, exposure, gain and calibration state. Calibration must match every\nlight in a merged group. Flats require the same night; darks require matching\nexposure and known temperatures within 3 degrees C. Already calibrated/registered\nlights receive no additional calibration; unknown calibration is flagged and opt-in.\nMasters stay separate and require explicit selection in your stacking software.\nDo not combine stacks with constituent subs or overlapping live-stack snapshots.\nExports include a manifest and workflow notes. Actual stacking uses external software.\n\nDELETE ALL ARCHIVE DATA\nSettings has a red Delete all archive data button. It shows the selected archive\npath and file count. Drag the slider fully right, then press Delete permanently.\nClosing the dialog cancels. This removes indexed archive FITS, saved session JSON,\nanalysis/worker caches and reports. Source mirrors and unindexed files are retained.\nOnly the selected archive is affected. Cloud-synced deletions propagate and there is\nno undo. The repository Clear button remains solely a filter reset.\n\nSUPPORTED FILES\n.fit, .fits, .fts and .gz variants; primary/IMAGE HDUs; 8/16/32/64-bit integer or\n32/64-bit floating data; mono/CFA and up to four colour planes. Tile-compressed .fz,\nmulti-frame cubes, TIFF, JPEG, PNG and videos need other tools/conversion.\nFITS pixels/headers are never rewritten. Existing export projects are never replaced.\nRepository tools index existing FITS, verify checksums and export a CSV catalogue.\n\nVALIDATION\nCompiled against Microsoft .NET Framework 4.8 reference assemblies. Generated-data\nregressions exercise FITS parsing, streaming scans, SHA-256 copying/deduplication,\nper-file failure recovery, caches, repeated checkpoints, DWARF calibration channels,\nsession exports, archive-reset boundaries, rotation and solver protocol handling.\nSee Validation.txt in the portable ZIP for exact counts and executable checks.\nWindows-native deletion/identity tests are included in test.ps1 but could not run in\nthis Linux build environment. WPF interaction, live Drive and the slider confirmation\nneed Windows validation. No real telescope data or authenticated plate solve was\navailable here. The ASTAP protocol test uses a test double, not real sky solving.\n\nCatalogue: OpenNGC, Mattia Verga, https://github.com/mattiaverga/OpenNGC, CC-BY-SA-4.0.\nAttribution and reproducible source are included in AstroArchive_Source.zip.\n";
