s[1]).Items.Count!=3)throw new Exception("Export choices are missing.");SelectContextRow(all[2]);if(SelectedFiles().Count!=1||files.SelectedItem!=all[2])throw new Exception("Right-click did not select an unselected file.");files.SelectedItems.Clear();if(Window.FindName("RepositoryButton")!=null)throw new Exception("Repository picker remains in the header.");Window.Measure(new Size(1220,820));Window.Arrange(new Rect(0,0,1220,820));Window.UpdateLayout();Capture(Path.Combine(output,"AstroArchive_UI.png"));((TabControl)Window.FindName("MainTabs")).SelectedIndex=1;G("ImportGrid").ItemsSource=all;Window.UpdateLayout();Capture(Path.Combine(output,"AstroArchive_Import_UI.png"));File.WriteAllText(Path.Combine(output,"ui-smoke.txt"),"PASS: XAML load, repository search/aliases, Clear filter reset, analysis defaults, target summary bindings, selection-aware context menus, export choices, compact repository path, layout and import tab rendering.");}
