 public class FormWindow {
  public Window Window;StackPanel content;StackPanel buttons;
  public FormWindow(Window owner,string title,int width,int height){Window=new Window{Owner=owner,Title=title,Width=width,Height=height,MinWidth=400,MinHeight=360,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=new SolidColorBrush(Color.FromRgb(245,247,249)),FontFamily=new FontFamily("Segoe UI"),FontSize=13};foreach(var key in owner.Resources.Keys)Window.Resources[key]=owner.Resources[key];var grid=new Grid{Margin=new Thickness(24)};grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});content=new StackPanel();grid.Children.Add(new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});buttons=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,18,0,0)};Grid.SetRow(buttons,1);grid.Children.Add(buttons);Window.Content=grid;}
  public void Add(UIElement element){content.Children.Add(element);}public void Text(string text,bool heading=false){Add(new TextBlock{Text=text,TextWrapping=TextWrapping.Wrap,FontSize=heading?18:12,FontWeight=heading?FontWeights.SemiBold:FontWeights.Normal,Foreground=heading?new SolidColorBrush(Color.FromRgb(20,63,72)):Brushes.SlateGray,Margin=new Thickness(0,heading?8:0,0,12)});}
  public TextBox Input(string label,string val){Add(new TextBlock{Text=label,Margin=new Thickness(0,6,0,5),Foreground=Brushes.SlateGray,FontSize=12});var t=new TextBox{Text=val??"",Margin=new Thickness(0,0,0,5)};Add(t);return t;}
  public ComboBox Select(string label,string[] values,string selected){Add(new TextBlock{Text=label,Margin=new Thickness(0,8,0,5),Foreground=Brushes.SlateGray,FontSize=12});var c=new ComboBox{ItemsSource=values,SelectedItem=selected};Add(c);return c;}
  public CheckBox Check(string label,bool initial){var c=new CheckBox{Content=new TextBlock{Text=label,TextWrapping=TextWrapping.Wrap},IsChecked=initial,Margin=new Thickness(0,14,0,3)};Add(c);return c;}
  public Button Button(string label,Action action){var b=new Button{Content=label,HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,5,0,12)};b.Click+=(s,e)=>action();Add(b);return b;}
  public void Accept(string text,Func<bool> valid,bool destructive=false){var cancel=new Button{Content="Cancel",IsCancel=true};cancel.Click+=(s,e)=>Window.DialogResult=false;buttons.Children.Add(cancel);var ok=new Button{Content=text,IsDefault=!destructive,Background=new SolidColorBrush(destructive?Color.FromRgb(183,40,51):Color.FromRgb(23,107,116)),Foreground=Brushes.White};ok.Click+=(s,e)=>{if(valid())Window.DialogResult=true;};buttons.Children.Add(ok);}
  public void CloseOnly(){var close=new Button{Content="Close",IsCancel=true};close.Click+=(s,e)=>Window.Close();buttons.Children.Add(close);}public bool Show(){return Window.ShowDialog()==true;}
